def is_rated(n, ratings):
    ratings_changed = False
    for i in range(1, n):
        if ratings[i][0] != ratings[i-1][0]:
            ratings_changed = True
    if ratings_changed:
        return "rated"
    else:
        for i in range(1, n):
            if ratings[i][0] < ratings[i-1][0] and ratings[i][1] > ratings[i-1][1]:
                return "rated"
        return "unrated"

n = int(input())
ratings = [tuple(map(int, input().split())) for _ in range(n)]
print(is_rated(n, ratings))
