def determine_rating(n, ratings):
    changed = False
    for i in range(1, n):
        if ratings[i][0] != ratings[i-1][0]:
            changed = True
            break

    if not changed:
        return "unrated"

    for i in range(1, n):
        if ratings[i][1] > ratings[i-1][1]:
            if ratings[i][0] < ratings[i-1][0]:
                return "maybe"
            else:
                return "rated"

    return "unrated"

# Example usage
n = int(input())
ratings = [tuple(map(int, input().split())) for _ in range(n)]
print(determine_rating(n, ratings))
```

