def check_rating_status(n, ratings):
    unchanged = True
    strictly_decreasing = True

    for i in range(1, n):
        if ratings[i][0] != ratings[i][1]:
            unchanged = False
        if ratings[i][0] < ratings[i-1][0]:
            strictly_decreasing = False

    if unchanged:
        return "maybe"
    elif strictly_decreasing:
        return "unrated"
    else:
        return "rated"

# Input reading
n = int(input())
ratings = [tuple(map(int, input().split())) for _ in range(n)]

# Output the result
print(check_rating_status(n, ratings))
